 app.innerHTML=`<section class="card"><div class="post-row">${avatar(id)}<div class="post-body"><h1>${esc(name(id))}</h1><p>${esc(p.hangar_intro||p.bio||'Miembro de Gente de Vuelo.')}</p><p class="meta">Miembro desde ${date(p.created_at)}</p></div></div><dl class="profile-fields">${[['Actividad','aviation_role'],['Licencia','aviation_license'],['Horas de vuelo','flight_hours'],['Aeropuerto base','home_airfield'],['Aeronaves','aircraft_flown'],['Simulador de vuelo','flight_simulators']].filter(([,k])=>p[k]!==null&&p[k]!==undefined&&p[k]!=='').map(([n,k])=>`<div><dt>${n}</dt><dd>${esc(p[k])}</dd></div>`).join('')}</dl>${own?link('Editar perfil','#perfil'):''}</section><div class="toolbar"><button data-hangar="posts">Publicaciones</button><button data-hangar="comments">Respuestas</button><button data-hangar="media">Multimedia</button><button data-hangar="trips">Travesías</button>${own?'<button data-hangar="saved">Guardados privados</button>':''}</div><div id="hangar-content"></div>`;
 const paint=async type=>{if(type==='comments')$('hangar-content').innerHTML=replied.map(c=>`<article class="card"><div class="meta">${date(c.created_at)}</div><p>${esc(c.deleted?'Comentario eliminado por su autor':c.content)}</p>${link('Ver conversación','#tema/'+c.topic_id+'/'+c.id)}</article>`).join('')||'<p>Sin respuestas públicas.</p>';else{let list=authored;if(type==='trips')list=list.filter(t=>t.category==='travesias');if(type==='media')list=list.filter(t=>media.some(m=>m.topic_id===t.id));if(type==='saved'){const rows=checked(await db.from('gdv_saved').select('topic_id').eq('user_id',user.id));list=topics.filter(t=>rows.some(s=>s.topic_id===t.id))}$('hangar-content').innerHTML=list.map(topicCard).join('')||'<p>Todavía no hay publicaciones en este apartado.</p>'}};app.querySelectorAll('[data-hangar]').forEach(b=>b.onclick=()=>busy(b,()=>paint(b.dataset.hangar)));await paint('posts');
